def solve(N, M, A, G):
    from collections import deque

    def bfs():
        max_score = 0
        queue = deque([(0, [A[0]])])  # Start from vertex 1 (index 0)
        visited = set()

        while queue:
            node, path = queue.popleft()
            if node == N - 1:  # Reached vertex N
                max_score = max(max_score, len(set(path)))
                continue

            for neighbor in G[node]:
                if neighbor not in visited and A[neighbor] >= path[-1]:
                    visited.add(neighbor)
                    queue.append((neighbor, path + [A[neighbor]]))
                    visited.remove(neighbor)

        return max_score

    return bfs()
